package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type TaxRec struct { // 01 TAX-REC, 13 bytes
	TrId     string          // PIC X(5) @0 len=5
	TrIncome decimal.Decimal // PIC 9(6)V99 @5 len=8
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string = "N" // PIC X len=1 = "N"
var WsTax decimal.Decimal = decimal.NewFromInt(0)      // PIC 9(7)V99 len=9 = 0
var WsNet decimal.Decimal = decimal.NewFromInt(0)      // PIC 9(7)V99 len=9 = 0
var WsTotalTax decimal.Decimal = decimal.NewFromInt(0) // PIC 9(9)V99 len=11 = 0
var WsCount int64 = 0                                  // PIC 9(3) len=3 = 0
var WsIncEd string                                     // PIC ZZZ,ZZ9.99 len=10
var WsTaxEd string                                     // PIC ZZZ,ZZ9.99 len=10
var WsNetEd string                                     // PIC ZZZ,ZZ9.99 len=10
var WsTotalEd string                                   // PIC ZZ,ZZZ,ZZ9.99 len=13

var curRec TaxRec

var taxLines []string
var taxIdx int

func pow10(n int) int64 {
	r := int64(1)
	for i := 0; i < n; i++ {
		r *= 10
	}
	return r
}

func fit97(v decimal.Decimal) decimal.Decimal {
	iv := v.Shift(2).Truncate(0).IntPart()
	r := iv % 1000000000
	return decimal.New(r, -2)
}

func fit99(v decimal.Decimal) decimal.Decimal {
	iv := v.Shift(2).Truncate(0).IntPart()
	r := iv % 100000000000
	return decimal.New(r, -2)
}

func formatEdited(v decimal.Decimal, pattern string) string {
	dotIdx := strings.Index(pattern, ".")
	var intPat, fracPat string
	if dotIdx >= 0 {
		intPat = pattern[:dotIdx]
		fracPat = pattern[dotIdx+1:]
	} else {
		intPat = pattern
		fracPat = ""
	}
	intSlots := 0
	for _, ch := range intPat {
		if ch == 'Z' || ch == '9' {
			intSlots++
		}
	}
	fracSlots := 0
	for _, ch := range fracPat {
		if ch == 'Z' || ch == '9' {
			fracSlots++
		}
	}
	vt := v.Truncate(int32(fracSlots))
	av := vt.Abs()
	intPartDec := av.Truncate(0)
	intVal := intPartDec.IntPart()
	fracDec := av.Sub(intPartDec).Shift(int32(fracSlots)).Truncate(0)
	fracVal := fracDec.IntPart()
	p := pow10(intSlots)
	var modInt int64
	if p != 0 {
		modInt = intVal % p
	} else {
		modInt = intVal
	}
	intDigits := fmt.Sprintf("%0*d", intSlots, modInt)
	fracDigits := ""
	if fracSlots > 0 {
		fracDigits = fmt.Sprintf("%0*d", fracSlots, fracVal)
	}
	var sb strings.Builder
	digitIdx := 0
	significant := false
	for _, ch := range intPat {
		if ch == 'Z' || ch == '9' {
			d := intDigits[digitIdx]
			digitIdx++
			if ch == 'Z' && !significant {
				if d == '0' {
					sb.WriteByte(' ')
				} else {
					sb.WriteByte(d)
					significant = true
				}
			} else {
				sb.WriteByte(d)
				significant = true
			}
		} else if ch == ',' {
			if significant {
				sb.WriteByte(',')
			} else {
				sb.WriteByte(' ')
			}
		} else {
			sb.WriteRune(ch)
		}
	}
	if dotIdx >= 0 {
		sb.WriteByte('.')
		fIdx := 0
		for _, ch := range fracPat {
			if ch == 'Z' || ch == '9' {
				d := fracDigits[fIdx]
				fIdx++
				sb.WriteByte(d)
			} else {
				sb.WriteRune(ch)
			}
		}
	}
	return sb.String()
}

func isInputDone() bool {
	return WsEofFlag == "Y"
}

func MainPara() {
	taxLines = nil
	taxIdx = 0
	f, err := os.Open("input.dat")
	if err != nil {
		if !os.IsNotExist(err) {
			fmt.Fprintln(os.Stderr, err.Error())
			os.Exit(1)
		}
	} else {
		sc := bufio.NewScanner(f)
		for sc.Scan() {
			taxLines = append(taxLines, sc.Text())
		}
		if serr := sc.Err(); serr != nil {
			fmt.Fprintln(os.Stderr, serr.Error())
			f.Close()
			os.Exit(1)
		}
		f.Close()
	}
	ReadPara()
	for !isInputDone() {
		ProcessPara()
	}
	WsTotalEd = formatEdited(WsTotalTax, "ZZ,ZZZ,ZZ9.99")
	countStr := fmt.Sprintf("%03d", WsCount)
	line := "TAXPAYERS: " + countStr + " TOTAL TAX: " + WsTotalEd
	os.Stdout.WriteString(line + "\n")
}

func ReadPara() {
	if taxIdx >= len(taxLines) {
		WsEofFlag = "Y"
		return
	}
	line := taxLines[taxIdx]
	taxIdx++
	if len(line) < 13 {
		line += strings.Repeat(" ", 13-len(line))
	} else if len(line) > 13 {
		line = line[:13]
	}
	curRec.TrId = line[0:5]
	incStr := line[5:13]
	var n int64 = 0
	for i := 0; i < len(incStr); i++ {
		c := incStr[i]
		var d int64
		if c >= '0' && c <= '9' {
			d = int64(c - '0')
		} else if c == ' ' {
			d = 0
		} else {
			d = 0
		}
		n = n*10 + d
	}
	curRec.TrIncome = decimal.New(n, -2)
}

func ProcessPara() {
	d10000 := decimal.NewFromInt(10000)
	d40000 := decimal.NewFromInt(40000)
	d1000 := decimal.NewFromInt(1000)
	d7000 := decimal.NewFromInt(7000)
	d010 := decimal.New(10, -2)
	d020 := decimal.New(20, -2)
	d030 := decimal.New(30, -2)
	if curRec.TrIncome.Cmp(d10000) <= 0 {
		v := curRec.TrIncome.Mul(d010).Round(2)
		WsTax = fit97(v)
	} else {
		if curRec.TrIncome.Cmp(d40000) <= 0 {
			diff := curRec.TrIncome.Sub(d10000)
			v := d1000.Add(diff.Mul(d020)).Round(2)
			WsTax = fit97(v)
		} else {
			diff := curRec.TrIncome.Sub(d40000)
			v := d7000.Add(diff.Mul(d030)).Round(2)
			WsTax = fit97(v)
		}
	}
	WsNet = fit97(curRec.TrIncome.Sub(WsTax).Truncate(2))
	WsTotalTax = fit99(WsTotalTax.Add(WsTax).Truncate(2))
	WsCount = (WsCount + 1) % 1000
	WsIncEd = formatEdited(curRec.TrIncome, "ZZZ,ZZ9.99")
	WsTaxEd = formatEdited(WsTax, "ZZZ,ZZ9.99")
	WsNetEd = formatEdited(WsNet, "ZZZ,ZZ9.99")
	line := curRec.TrId + " " + WsIncEd + " " + WsTaxEd + " " + WsNetEd
	os.Stdout.WriteString(line + "\n")
	ReadPara()
}

func main() {
	MainPara()
}
